public class SafeAverage {
    public static void main(String[] args) {
        int total = 90;
        int count = 3;

        if (count == 0) {
            System.out.println("Cannot calculate an average: count is zero.");
        } else {
            int average = total / count;
            System.out.println("Average: " + average);
        }
    }
}

public class DecimalAverage {
    public static void main(String[] args) {
        int total = 90;
        int count = 4;

        if (count == 0) {
            System.out.println("Cannot calculate an average: count is zero.");
        } else {
            double average = (double) total / count;
            System.out.println("Average: " + average);
        }
    }
}

